/* Legal library. type: Primary legislation | Subsidiary legislation | Regulatory guidance | Industry practice | Legal interpretation */
const LEGAL=[
{id:'L1',type:'Statute',act:'Insurance Act, Cap. 487',sec:'s.2',subject:'Definition of general insurance business',text:'“General insurance business” means insurance business of any class or classes not being long-term insurance business. Micro-insurance business is defined separately.',plain:'Anything that is not life/long-term business is general business. The Act itself does not list the classes.',practice:'Look to the Insurance Regulations (reg.10) for the actual class list.',src:'S2',status:'VERIFIED'},
{id:'L2',type:'Regulation',act:'Insurance Regulations, L.N. 312/1986',sec:'reg.10 & Third Schedule Part A',subject:'Classes of general insurance business',text:'An insurer carrying on general insurance business must keep separate accounts for the classes in Part A of the Third Schedule: 01 Aviation … 14 Miscellaneous Insurance (14 classes).',plain:'These 14 classes are the legal classification; the IRA licence codes 01–14 follow them.',practice:'Products such as “PSV motor” or “domestic package” are commercial groupings that sit within one or more of these classes.',src:'S13',status:'VERIFIED'},
{id:'L3',type:'Statute',act:'Insurance Act, Cap. 487',sec:'s.3A',subject:'Objects and functions of IRA',text:'Supervision and regulation of insurance and reinsurance business, conduct standards, licensing, prudential guidelines, public education and protection of policyholders.',plain:'IRA is the regulator and supervisor.',practice:'Complaints, licensing checks and statistics come from IRA.',src:'S2',status:'VERIFIED'},
{id:'L4',type:'Statute',act:'Insurance Act, Cap. 487',sec:'s.19',subject:'Only licensed persons to carry on insurance business',text:'Insurance business may only be carried on by persons licensed under the Act.',plain:'Buy only from licensed insurers and intermediaries.',practice:'Check the current s.184 notice before placing business.',src:'S2',status:'VERIFIED'},
{id:'L5',type:'Statute',act:'Insurance Act, Cap. 487',sec:'s.23 & Second Schedule',subject:'Minimum capital',text:'General insurers: the highest of KES 600 million, risk-based capital, or 20% of the preceding year’s net earned premium.',plain:'Insurers must hold minimum capital.',practice:'Insurer-level capital adequacy is not published in this portal.',src:'S2',status:'VERIFIED'},
{id:'L6',type:'Statute',act:'Insurance Act, Cap. 487',sec:'ss.30–31',subject:'Licensing of insurers',text:'Application in the prescribed form (s.30); the licence remains in force until cancelled under s.196 (s.31).',plain:'Licensing is by IRA and continues until cancelled.',practice:'The annual s.184 notice lists who is authorised that year.',src:'S2',status:'VERIFIED'},
{id:'L7',type:'Statute',act:'Insurance Act, Cap. 487',sec:'s.67C(2)(i)',subject:'Statutory management',text:'IRA notices cite s.67C(2)(i) when placing an insurer under statutory management and appointing PCF as statutory manager.',plain:'The regulator can take control of a failing insurer.',practice:'The insurer may not write new business; policyholders are told to seek cover elsewhere; claims move to the PCF process.',src:'S27',status:'VERIFIED'},
{id:'L8',type:'Statute',act:'Insurance Act, Cap. 487',sec:'ss.150–153',subject:'Intermediary licensing',text:'s.150 only licensed brokers, agents, risk managers, motor assessors and related professionals may operate; s.151 application; s.152 disqualifications; s.153 licensing and re-licensing.',plain:'Intermediaries need an IRA licence.',practice:'Detailed qualification criteria were not extracted.',src:'S2',status:'VERIFIED'},
{id:'L9',type:'Statute',act:'Insurance Act, Cap. 487',sec:'s.156',subject:'Advance payment of premiums (“cash and carry”)',text:'(1) “No insurer shall assume a risk in Kenya” until the premium is received. (2) Intermediaries may not receive premiums on an insurer’s behalf. (3)–(4) Penalty of 20% of unremitted premium on an intermediary; fines or imprisonment for officers. (5)–(6) Insurer must pay the intermediary’s commission within 30 days of receiving the premium; KES 5 million per contravention, payable to the PCF.',plain:'No premium, no cover. Pay the insurer directly.',practice:'Courts have treated full payment as a condition precedent (2023 bond case).',src:'S2',status:'VERIFIED'},
{id:'L10',type:'Statute',act:'Insurance Act, Cap. 487',sec:'s.169',subject:'Insurance Appeals Tribunal',text:'The Cabinet Secretary may by Gazette notice establish a Tribunal to hear appeals under the Act.',plain:'There is a specialist appeal body.',practice:'Used after an IRA complaint determination (s.204A).',src:'S2',status:'VERIFIED'},
{id:'L11',type:'Statute',act:'Insurance Act, Cap. 487',sec:'s.179',subject:'Policyholders Compensation Fund',text:'Establishes the PCF to compensate claimants of insurers under statutory management or whose licence is cancelled; Board of Trustees; contributions by policyholders and insurers.',plain:'A safety net if your insurer fails — capped per claim.',practice:'Limit KSh 500,000 per claim from 1 Jan 2026 (PCF notice).',src:'S2',status:'VERIFIED'},
{id:'L12',type:'Statute',act:'Insurance Act, Cap. 487',sec:'s.184',subject:'Notice of licensed persons',text:'The Commissioner publishes notice of persons authorised to transact insurance business (the annual licensed-entities list).',plain:'The official list of who is licensed.',practice:'This portal’s active-insurer statuses come from the 30 March 2026 notice.',src:'S1',status:'VERIFIED'},
{id:'L13',type:'Statute',act:'Insurance Act, Cap. 487',sec:'s.196',subject:'Cancellation of licence',text:'Grounds include contravening the Act, unpaid judgments three months after final adjudication, unsound practice and liquidation. A cancelled insurer may not enter new contracts.',plain:'IRA can cancel licences.',practice:'Existing contracts continue subject to s.196(5).',src:'S2',status:'VERIFIED'},
{id:'L14',type:'Statute',act:'Insurance Act, Cap. 487',sec:'s.203',subject:'Settlement of claims — 90 days',text:'(1) Once relevant documents are submitted, the insurer must admit or deny liability, determine the amount, establish the claimant’s identity and pay “within ninety days of the date of the reporting of the claim” (or of a court’s determination of liability). The Commissioner may extend by up to 30 days on the insurer’s application. (1A) Not applicable to index-based or micro-insurance claims. (2) Assessment report copy to the claimant. (3)–(4) 5% penalty on unpaid amounts after the period, payable to the PCF Board. (5) Non-payment: insurer deemed unable to pay its debts (s.123).',plain:'Most claims must be decided and paid within 90 days of being reported, extendable by 30 days.',practice:'Keep proof of the reporting date and of document submission.',src:'S2',status:'VERIFIED'},
{id:'L15',type:'Statute',act:'Insurance Act, Cap. 487',sec:'s.204A',subject:'Complaints to the Commissioner',text:'Any insurance customer may lodge a written complaint with the Commissioner against a regulated entity. The determination binds the parties; appeal to the Tribunal within 30 days.',plain:'You can complain to IRA in writing.',practice:'complaints@ira.go.ke (IRA annual report 2024).',src:'S2',status:'VERIFIED'},
{id:'L16',type:'Statute',act:'Insurance (Motor Vehicle Third Party Risks) Act, Cap. 405',sec:'s.4–5',subject:'Compulsory third party motor insurance',text:'Motor vehicles used on a road must be insured against third party risks under a policy complying with s.5.',plain:'Third party motor cover is compulsory.',practice:'Keep a valid certificate of insurance.',src:'S10',status:'VERIFIED'},
{id:'L17',type:'Statute',act:'Work Injury Benefits Act, Cap. 236',sec:'s.7(1)',subject:'Compulsory employer insurance',text:'Every employer shall obtain and maintain an insurance policy with an approved insurer for any liability it may incur under the Act to its employees.',plain:'Employers must insure work-injury liability.',practice:'Includes domestic workers.',src:'S9',status:'VERIFIED'},
{id:'L18',type:'Statute',act:'Data Protection Act, Cap. 411C (No. 24 of 2019)',sec:'s.25',subject:'Principles of data protection',text:'Data controllers and processors must ensure personal data is processed lawfully, fairly and transparently, for explicit and legitimate purposes, among other principles.',plain:'Insurers and intermediaries handle personal and health data under this Act.',practice:'Proposal forms, medical claims and KYC files all involve personal data; health data is sensitive personal data.',src:'S31',status:'VERIFIED'},
{id:'L19',type:'Statute',act:'Proceeds of Crime and Anti-Money Laundering Act, 2009',sec:'Reporting institutions',subject:'AML/CFT obligations',text:'IRA guidance treats underwriters and intermediaries in life and investment-related insurance as reporting institutions.',plain:'KYC and suspicious-transaction reporting apply — most clearly to life/investment products.',practice:'How far each duty applies to purely general business has not been verified.',src:'S11',status:'REPORTED'},
{id:'L20',type:'Guidance',act:'IRA Insurance (AML/CFT) Guidelines, 2020',sec:'Issued under s.3A(g)',subject:'Sector AML/CFT guidance',text:'Sets out customer due diligence, record keeping and reporting expectations; independent AML audit report to IRA by 31 January (2025 guidance note, reported).',plain:'IRA’s detailed AML expectations.',practice:'Read the IRA original; the copy checked here is a secondary host.',src:'S11',status:'REPORTED'},
{id:'L21',type:'Practice',act:'AKI notice (July 2019)',sec:'—',subject:'Cash-and-carry rollout',text:'AKI told the market all policies would be bought on a cash-and-carry basis from 23 July 2019.',plain:'Industry implementation of s.156.',practice:'Practice, not law — s.156 is the legal basis.',src:'S23',status:'REPORTED'},
{id:'L22',type:'Practice',act:'Insurer service charters (e.g. CIC General, 2022)',sec:'—',subject:'Internal claims targets',text:'Example: discharge voucher within 5 days (motor) / 14 days (non-motor) after assessor’s reports.',plain:'Insurers publish their own service targets.',practice:'These are commitments, not statutory deadlines.',src:'S33',status:'VERIFIED'},
{id:'L23',type:'Court Decision',act:'High Court — AIBK petition (2021)',sec:'s.156',subject:'Constitutionality of the 2019 amendment',text:'Brokers challenged s.156 as amended by the Insurance (Amendment) Act No. 11 of 2019.',plain:'The cash-and-carry rule was tested in court.',practice:'Read the judgment for the holding before relying on it.',src:'S14',status:'VERIFIED'},
{id:'L24',type:'Court Decision',act:'High Court appeal (23 Aug 2023)',sec:'s.156(1)',subject:'Full premium for multi-year bonds',text:'Full premium treated as a condition precedent before a 3-year bond could be issued.',plain:'Partial payment may mean no cover.',practice:'Collect the full premium for the full term where s.156 applies.',src:'S34',status:'VERIFIED'}];

